    'home.hero.headline' => 'Aterriza en cualquier lugar. Conéctate al instante.',
    'home.hero.social_proof' => 'Elegida por viajeros de Lagos, Accra, Nairobi y más allá · más de 190 países cubiertos · Se activa en menos de 3 minutos',
    'home.hero.spot_link_label' => 'Explora NaaraSim',
